-- Phase 93E: segregation of duties. Rules name entitlements, never job titles, and are always configurable per organization.
-- quality: allow-nonconcurrent-index reason=new-empty-identity-governance-tables

create table public.sod_rule_definitions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,key text not null,name text not null,description text not null default '',rule_type text not null check(rule_type in('toxic_combination','approval_execution_conflict','creator_approver_conflict','payment_reconciliation_conflict','admin_audit_conflict','custom')),conflicting_entitlement_refs text[] not null check(cardinality(conflicting_entitlement_refs)>=2),scope text not null default 'organization' check(scope in('organization','store')),severity text not null check(severity in('low','medium','high','critical')),mitigation_allowed boolean not null default true,status text not null default 'draft' check(status in('draft','active','deprecated','retired')),version integer not null default 1 check(version>0),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,key));

create table public.sod_conflicts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,identity_id uuid not null references public.governed_identities(id) on delete restrict,rule_id uuid not null references public.sod_rule_definitions(id) on delete restrict,rule_version integer not null,entitlement_refs text[] not null,detection text not null check(detection in('preventive','detective')),result text not null check(result in('conflict_blocked','conflict_mitigated','conflict_accepted')),severity text not null check(severity in('low','medium','high','critical')),status text not null default 'open' check(status in('open','mitigated','accepted','resolved')),request_id uuid references public.access_requests(id) on delete set null,fingerprint text not null,detected_at timestamptz not null default now(),resolved_at timestamptz,unique(organization_id,fingerprint));

create table public.sod_mitigations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,conflict_id uuid not null references public.sod_conflicts(id) on delete restrict,kind text not null check(kind in('mitigation','acceptance')),severity text not null check(severity in('low','medium','high','critical')),control_description text not null,owner_ref text not null,reason text not null,expires_at timestamptz not null,approved_by uuid[] not null default '{}',status text not null default 'active' check(status in('active','expired','revoked')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(kind<>'acceptance' or severity<>'critical' or cardinality(approved_by)>=2),check(kind<>'mitigation' or cardinality(approved_by)>=1));

create index sod_rules_board_idx on public.sod_rule_definitions(organization_id,status,severity);
create index sod_conflicts_board_idx on public.sod_conflicts(organization_id,status,severity,detected_at);
create index sod_conflicts_identity_idx on public.sod_conflicts(identity_id);
create index sod_conflicts_rule_idx on public.sod_conflicts(rule_id);
create index sod_conflicts_request_idx on public.sod_conflicts(request_id) where request_id is not null;
create index sod_mitigations_conflict_idx on public.sod_mitigations(conflict_id);
create index sod_mitigations_expiry_idx on public.sod_mitigations(status,expires_at);

do $$declare t text;begin foreach t in array array['sod_rule_definitions','sod_conflicts','sod_mitigations'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
